    fn next_random_qm31(state: &mut u64) -> QM31 {
        let mut limb = || {
            *state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            M31((*state % u64::from(P)) as u32)
        };
        QM31 {
            c0: CM31::new(limb(), limb()),
            c1: CM31::new(limb(), limb()),
