        fn next(state: &mut u64) -> M31 {
            *state ^= *state >> 12;
            *state ^= *state << 25;
            *state ^= *state >> 27;
            M31((state.wrapping_mul(0x2545_f491_4f6c_dd1d) as u32) % P)
        }

        fn cm31(state: &mut u64) -> CM31 {
            CM31::new(next(state), next(state))
