            let mut coefficients = [QM31::ZERO; 73];
            coefficients[degree] = QM31::ONE;
            let expected = x.pow(degree as u64);
            assert_eq!(
                qm31_evaluate_degree72_radix8(&coefficients, x),
                expected,
